from __future__ import annotations


def build_realtime_paper_ui() -> str:
    return r'''<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>实时模拟交易 · Quant Data Gateway</title>
<style>
:root{--bg:#0b1020;--panel:#101827;--panel2:#172033;--line:#283956;--text:#dbeafe;--muted:#91a7c7;--blue:#3b82f6;--green:#22c55e;--red:#ef4444;--yellow:#f59e0b}
*{box-sizing:border-box}html,body{height:100%;margin:0}body{font-family:Segoe UI,Microsoft YaHei,Arial,sans-serif;background:var(--bg);color:var(--text);overflow:hidden}.app{height:100vh;display:grid;grid-template-rows:56px 1fr 78px;grid-template-columns:330px 1fr 430px;grid-template-areas:"top top top" "side main right" "log log log"}.top{grid-area:top;background:#101827;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;padding:0 16px;overflow:hidden}.side{grid-area:side;background:#0f172a;border-right:1px solid var(--line);padding:14px;overflow:auto}.main{grid-area:main;padding:12px;overflow:auto}.right{grid-area:right;background:#0f172a;border-left:1px solid var(--line);padding:12px;overflow:auto}.log{grid-area:log;background:#0f172a;border-top:1px solid var(--line);padding:8px 12px;overflow:auto;font-family:Consolas,monospace;font-size:12px;color:#9fb4d4}.brand{font-weight:900;color:#bfdbfe;font-size:18px;white-space:nowrap}.dot{width:10px;height:10px;border-radius:50%;background:var(--green);box-shadow:0 0 14px var(--green);flex:0 0 auto}.grow{flex:1;min-width:0}.pill{display:inline-flex;align-items:center;border:1px solid #30405d;background:#1f2a44;color:#bfdbfe;border-radius:999px;padding:5px 9px;font-size:12px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.panel,.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;overflow:hidden}.panel-h{min-height:44px;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:0 12px;background:#141e32;border-bottom:1px solid var(--line);font-weight:900}.panel-b{padding:12px}.section{font-size:13px;color:#9fb4d4;margin:12px 0 7px}input,select,textarea{width:100%;background:#1f2937;color:#e5e7eb;border:1px solid #374151;border-radius:10px;padding:9px 11px;outline:none}textarea{min-height:92px;resize:vertical;line-height:1.45}button{border:0;background:#2563eb;color:#fff;border-radius:10px;padding:9px 12px;font-weight:800;cursor:pointer;white-space:nowrap}.btn2{background:#253149;color:#c7d2fe}.btn-green{background:#16a34a}.btn-red{background:#991b1b}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}.cards{display:grid;grid-template-columns:repeat(4,minmax(130px,1fr));gap:8px;margin-bottom:10px}.card{padding:10px;min-width:0}.card span{display:block;color:var(--muted);font-size:11px}.card b{display:block;text-align:right;font-size:19px;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:#0f172a;max-height:330px}table{width:100%;border-collapse:collapse;font-size:13px;min-width:1060px}th,td{border-bottom:1px solid rgba(38,54,79,.8);padding:8px;text-align:right;white-space:nowrap;vertical-align:top}th:first-child,td:first-child,th:nth-child(2),td:nth-child(2),th:nth-child(3),td:nth-child(3){text-align:left}td.reason,td.evidence{white-space:normal;min-width:220px;line-height:1.45;overflow-wrap:anywhere}th{position:sticky;top:0;background:#182238;color:#93c5fd}.muted{color:var(--muted)}.up{color:#fca5a5}.down{color:#86efac}.warn{color:#fcd34d}.hint{font-size:12px;line-height:1.55;color:#9fb4d4;background:#0d1428;border:1px solid #26364f;border-radius:12px;padding:10px;margin-top:10px;overflow-wrap:anywhere}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.symbol-tabs{display:flex;gap:6px;flex-wrap:wrap}.symbol-tabs button{padding:6px 9px;background:#1f2a44;color:#bfdbfe}.symbol-tabs button.active{background:#2563eb;color:#fff}.mini{font-size:11px;color:#91a7c7;line-height:1.4}.pos-row{display:grid;grid-template-columns:70px 1fr;gap:8px;border-bottom:1px solid rgba(38,54,79,.7);padding:7px 0}.pos-row b{color:#bfdbfe}.step-list{margin:0;padding-left:18px}.step-list li{margin:5px 0}@media(max-width:1180px){body{overflow:auto}.app{height:auto;min-height:100vh;grid-template-columns:1fr;grid-template-rows:56px auto auto auto 78px;grid-template-areas:"top" "side" "main" "right" "log"}.cards{grid-template-columns:repeat(2,1fr)}.table-wrap{max-height:420px}}
</style>
<style>
.auto-box{margin-top:12px}.compact{min-height:54px}.auto-actions{margin:8px 0}.strategy-mini{display:grid;grid-template-columns:1fr;gap:6px;max-height:170px;overflow:auto;padding-right:2px}.strategy-mini label{display:flex;gap:8px;align-items:flex-start;background:#121c31;border:1px solid #26364f;border-radius:10px;padding:7px;font-size:12px;line-height:1.35}.strategy-mini input{width:auto;margin-top:2px}.strategy-mini b{color:#bfdbfe}.config-mini{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}.config-mini div{background:#121c31;border:1px solid #26364f;border-radius:9px;padding:7px;font-size:12px;color:#91a7c7}.config-mini b{display:block;color:#dbeafe;font-size:13px;margin-top:2px;overflow-wrap:anywhere}.risk-grid input,.risk-grid select{padding:7px 9px}.tag{display:inline-flex;align-items:center;border:1px solid #30405d;border-radius:999px;background:#172033;color:#bfdbfe;padding:2px 7px;margin:2px;font-size:11px}.guide-strip,.strategy-summary{border:1px solid #345177;background:#101b31;color:#bfdbfe;border-radius:12px;padding:9px;font-size:12px;line-height:1.55;margin-top:10px;overflow-wrap:anywhere}.strategy-summary{max-height:76px;overflow:auto}.strategy-summary b{display:block;color:#e0f2fe}
</style>
</head>
<body>
<div class="app">
  <header class="top"><span class="dot"></span><div class="brand">实时模拟交易</div><span class="pill">研究辅助，不构成投资建议 · paper_only · 不连接真实券商</span><div class="grow"></div><button class="btn2" onclick="location.href='/auto-trading'">自动交易总控台</button><button class="btn2" onclick="location.href='/backtest'">历史回测</button><button class="btn2" onclick="location.href='/screener'">筛选系统</button><button class="btn2" onclick="location.href='/ui'">行情监控</button></header>
  <aside class="side">
    <div class="section">监控标的，逗号或换行分隔</div><textarea id="symbols">300750,600438,510300</textarea>
    <div class="grid2">
      <div><div class="section">初始资金</div><input id="cash" type="number" value="100000"></div>
      <div><div class="section">自动频率</div><select id="interval"><option value="5">5秒</option><option value="15" selected>15秒</option><option value="30">30秒</option><option value="60">60秒</option></select></div>
      <div><div class="section">交易周期</div><select id="horizon"><option value="intraday_paper">盘中模拟</option><option value="short_term">短线</option><option value="swing">中线</option><option value="position">长线</option><option value="dca">定投</option><option value="hybrid">混合</option></select></div>
      <div><div class="section">手动观察价</div><input id="tickPrice" type="number" value="420"></div>
    </div>
    <div class="row" style="margin-top:12px"><button class="btn-green" onclick="startEngine()">启动自动模拟</button><button class="btn2" onclick="stopEngine()">停止</button><button onclick="runOneCycle('manual')">执行一轮模拟</button></div>
    <div class="hint">启动后页面会立即跑一轮，然后按频率循环。交易时段使用当前真实行情/缓存快照，休市时显示为纸面观察回放，不伪装真实盘中成交。多只股票会逐只生成信号，右上方标签可分别查看；手动观察价只用于页面说明，不作为自动交易行情。</div>
    <div class="panel auto-box">
      <div class="panel-h"><span>自动交易配置</span><button class="btn2" onclick="loadAutoConfig(true)">读取总控台</button></div>
      <div class="panel-b">
        <div id="paperConfigSummary" class="hint">读取总控台配置中...</div>
        <div class="row auto-actions"><button class="btn2" onclick="selectPaperPreset('balanced')">均衡入门</button><button class="btn2" onclick="selectPaperPreset('defensive')">防守学习</button><button class="btn2" onclick="selectPaperPreset('etf_rotation')">ETF轮动</button><button onclick="savePaperConfig()">保存配置</button></div>
        <div class="section">策略组合（可自行选择）</div>
        <textarea id="strategyCombo" class="compact" oninput="renderPaperStrategyCatalog(autoConfig||{})">score_driven, low_position, avoid_chasing_high, ma_repair, macd_cross, volume_breakout, atr_risk, position_risk, risk_control, event_driven, finance_quality, market_regime</textarea>
        <div id="paperStrategySummary" class="strategy-summary">策略会翻译成中文摘要，方便启动前确认。</div>
        <div class="section">策略目录</div>
        <div id="paperStrategyCatalog" class="strategy-mini"><span class="muted">加载中...</span></div>
        <div class="grid2 risk-grid">
          <div><div class="section">仓位模型</div><select id="positionSizing"><option value="score_weighted">评分加权</option><option value="atr_risk">ATR风险仓位</option><option value="volatility_target">波动率目标</option><option value="fixed_weight">固定权重</option><option value="core_satellite">核心-卫星</option><option value="cash_first_defensive">现金优先防守</option></select></div>
          <div><div class="section">最大单票%</div><input id="maxSinglePositionPct" type="number" value="20" step="0.5"></div>
          <div><div class="section">止损%</div><input id="stopLossPct" type="number" value="8" step="0.5"></div>
          <div><div class="section">止盈%</div><input id="takeProfitPct" type="number" value="18" step="0.5"></div>
          <div><div class="section">最大回撤%</div><input id="maxDrawdownPct" type="number" value="18" step="0.5"></div>
          <div><div class="section">现金保留%</div><input id="minCashPct" type="number" value="15" step="0.5"></div>
        </div>
        <div class="guide-strip">信息节点会进入模拟信号：财报、半年报、业绩预告、公告、重大负面、行业政策；数据过期时只允许观察/减仓，不自动新增仓位。</div>
      </div>
    </div>
  </aside>
  <main class="main">
    <div class="cards">
      <div class="card"><span>运行状态</span><b id="mStatus">--</b></div>
      <div class="card"><span>运行模式</span><b id="mMode">--</b></div>
      <div class="card"><span>下次循环</span><b id="mNext">--</b></div>
      <div class="card"><span>最近一轮</span><b id="mLast">--</b></div>
      <div class="card"><span>总权益</span><b id="mEquity">--</b></div>
      <div class="card"><span>现金/可用</span><b id="mCash">--</b></div>
      <div class="card"><span>持仓市值</span><b id="mMv">--</b></div>
      <div class="card"><span>总收益/回撤</span><b id="mRet">--</b></div>
    </div>
    <div class="panel">
      <div class="panel-h"><span>信号流</span><div class="row"><div id="symbolTabs" class="symbol-tabs"></div><button class="btn2" onclick="refreshAll()">刷新</button></div></div>
      <div class="panel-b"><div class="table-wrap"><table><thead><tr><th>时间</th><th>名称</th><th>代码</th><th>动作</th><th>总分</th><th>基本/技术/信息/资金/大盘</th><th>异常</th><th>目标仓位</th><th>模式</th><th>原因</th><th>依据</th></tr></thead><tbody id="signalRows"></tbody></table></div></div>
    </div>
    <div class="panel" style="margin-top:10px">
      <div class="panel-h"><span>订单流</span><span class="muted">拒单会显示风控原因；所有订单都是模拟订单</span></div>
      <div class="panel-b"><div class="table-wrap"><table><thead><tr><th>时间</th><th>代码</th><th>方向</th><th>状态</th><th>价格</th><th>股数</th><th>成交</th><th>原因</th></tr></thead><tbody id="orderRows"></tbody></table></div></div>
    </div>
  </main>
  <aside class="right">
    <div class="panel"><div class="panel-h"><span>模拟账户持仓</span><span id="symbolSummary" class="muted">--</span></div><div class="panel-b"><div id="positions" class="hint">--</div></div></div>
    <div class="panel" style="margin-top:10px"><div class="panel-h"><span>如何使用</span></div><div class="panel-b"><div class="hint"><ol class="step-list"><li>填入多只标的和初始资金。</li><li>点击“启动自动模拟”，页面会按频率循环抓取行情快照并生成纸面信号。</li><li>休市时只能做纸面回放观察，不能代表实时成交。</li><li>用“执行一轮模拟”手动跑一次，适合检查当前参数是否生效。</li></ol></div></div></div>
    <div class="panel" style="margin-top:10px"><div class="panel-h"><span>风控状态</span></div><div class="panel-b"><div id="riskBox" class="hint">--</div></div></div>
    <div class="panel" style="margin-top:10px"><div class="panel-h"><span>审计日志</span></div><div class="panel-b"><div id="auditBox" class="hint">--</div></div></div>
  </aside>
  <div class="log" id="log">Ready.</div>
</div>
<script>
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));
const fmt=(v,d=2)=>v==null||Number.isNaN(Number(v))?'--':Number(v).toFixed(d);
const money=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const pct=v=>fmt(v,2)+'%';
const cls=v=>Number(v)>=0?'up':'down';
let selectedSymbol='all',lastSignals=[],loopTimer=null,countTimer=null,cycleBusy=false,nextAt=null,lastMode='--',autoConfig=null;
function log(s){$('log').textContent=new Date().toLocaleTimeString()+' '+s+'\n'+$('log').textContent}
async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',...opt});if(!r.ok)throw new Error('HTTP '+r.status);return await r.json()}
function splitListText(v){return String(v||'').split(/[\s,，;；、|]+/).map(x=>x.trim()).filter(Boolean)}
function symbols(){return [...new Set(splitListText($('symbols').value))]}
function intervalSec(){return Math.max(5,Math.min(60,Number($('interval').value||15)))}
function num(id,fallback){const n=Number($(id)?.value);return Number.isFinite(n)?n:fallback}
function paperCombo(){return [...new Set(splitListText($('strategyCombo')?.value||''))]}
function paperStrategyLabel(key,cfg){
  const builtins={score_driven:'日常评分驱动',low_position:'低位修复',avoid_chasing_high:'高位追高过滤',ma_repair:'均线修复',macd_cross:'MACD金叉/多头',volume_breakout:'温和放量',atr_risk:'ATR波动过滤',position_risk:'仓位与止损',risk_control:'风险扣分',event_driven:'事件驱动',finance_quality:'财务质量',market_regime:'大盘情绪过滤'};
  const found=(cfg?.strategy_catalog||[]).find(x=>String(x.key)===String(key));
  return found?.name||builtins[key]||key;
}
function renderPaperStrategySummary(cfg){
  const box=$('paperStrategySummary');if(!box)return;
  const combo=paperCombo();
  const names=combo.length?combo.map(k=>paperStrategyLabel(k,cfg)).join('、'):'尚未选择策略';
  box.innerHTML=`<b>当前模拟策略：</b>${esc(names)}<br>止损 ${esc($('stopLossPct')?.value||'--')}% · 止盈 ${esc($('takeProfitPct')?.value||'--')}% · 最大回撤 ${esc($('maxDrawdownPct')?.value||'--')}% · 单票上限 ${esc($('maxSinglePositionPct')?.value||'--')}%`;
}
function setPaperCombo(list){$('strategyCombo').value=[...new Set((list||[]).map(x=>String(x||'').trim()).filter(Boolean))].join(', ');renderPaperStrategyCatalog(autoConfig);renderPaperStrategySummary(autoConfig)}
function collectPaperAutoConfig(){return {symbols:symbols(),strategy_family:'hybrid',strategy_combo:paperCombo(),position_sizing:$('positionSizing')?.value||'score_weighted',initial_cash:Number($('cash').value||100000),interval_seconds:intervalSec(),horizon:$('horizon').value,reset_account:false,risk_controls:{stop_loss_pct:num('stopLossPct',8),take_profit_pct:num('takeProfitPct',18),max_drawdown_pct:num('maxDrawdownPct',18),max_single_position_pct:num('maxSinglePositionPct',20),max_total_position_pct:80,min_cash_pct:num('minCashPct',15),max_daily_loss_pct:4,atr_risk_pct:1.5,cooldown_days:2},score_weights:{technical:.30,fundamental:.22,information:.20,fund_flow:.16,market_regime:.12},event_watch:{financial_reports:true,half_year_reports:true,earnings_preannouncements:true,exchange_announcements:true,major_negative_news:true,policy_industry_news:true,event_lookahead_days:21,blackout_before_days:2,blackout_after_days:1},data_requirements:{require_fresh_quote:true,block_stale_buy:true,require_score_provenance:true,require_info_snapshot:false,require_orderbook_when_available:true},source_page:'realtime-paper'}}
function renderPaperStrategyCatalog(cfg){const box=$('paperStrategyCatalog');if(!box)return;const catalog=cfg?.strategy_catalog||[];const selected=new Set(paperCombo());renderPaperStrategySummary(cfg);if(!catalog.length){box.innerHTML='<span class="muted">策略目录暂未返回，仍可手动输入策略 key。</span>';return}box.innerHTML=catalog.map(item=>{const key=String(item.key||''),on=selected.has(key);return `<label title="${esc(item.description||item.beginner_note||'')}"><input type="checkbox" data-strategy-key="${esc(key)}" ${on?'checked':''} onchange="togglePaperStrategy(this)"><span><b>${esc(item.name||key)}</b><br><span class="mini">${esc(item.category||'策略')} · ${esc(item.beginner_note||item.description||'')}</span></span></label>`}).join('')}
function togglePaperStrategy(el){const set=new Set(paperCombo());if(el.checked)set.add(el.dataset.strategyKey);else set.delete(el.dataset.strategyKey);setPaperCombo([...set])}
function applyPaperConfig(cfg){if(!cfg)return;autoConfig=cfg;if((cfg.symbols||[]).length)$('symbols').value=cfg.symbols.join(', ');if(cfg.interval_seconds!=null)$('interval').value=String(cfg.interval_seconds);if(cfg.initial_cash!=null)$('cash').value=cfg.initial_cash;if((cfg.strategy_combo||[]).length)$('strategyCombo').value=cfg.strategy_combo.join(', ');if(cfg.position_sizing)$('positionSizing').value=cfg.position_sizing;const r=cfg.risk_controls||{};if(r.stop_loss_pct!=null)$('stopLossPct').value=r.stop_loss_pct;if(r.take_profit_pct!=null)$('takeProfitPct').value=r.take_profit_pct;if(r.max_drawdown_pct!=null)$('maxDrawdownPct').value=r.max_drawdown_pct;if(r.max_single_position_pct!=null)$('maxSinglePositionPct').value=r.max_single_position_pct;if(r.min_cash_pct!=null)$('minCashPct').value=r.min_cash_pct;renderPaperStrategyCatalog(cfg);renderPaperConfigSummary(cfg)}
function renderPaperConfigSummary(cfg){const combo=(cfg?.strategy_combo||paperCombo()).slice(0,8).map(k=>paperStrategyLabel(k,cfg));$('paperConfigSummary').innerHTML=`<b>当前配置</b><div class="config-mini"><div>股票池<b>${esc(symbols().join(', ')||'--')}</b></div><div>策略<b>${combo.map(esc).join('、')||'--'}</b></div><div>仓位模型<b>${esc($('positionSizing')?.value||'score_weighted')}</b></div><div>止损/止盈/回撤<b>${esc($('stopLossPct')?.value||'--')}% / ${esc($('takeProfitPct')?.value||'--')}% / ${esc($('maxDrawdownPct')?.value||'--')}%</b></div></div><span class="tag">技术面</span><span class="tag">资金面</span><span class="tag">信息面</span><span class="tag">基本面</span><span class="tag">大盘情绪</span>`;renderPaperStrategySummary(cfg)}
async function loadAutoConfig(apply=false){try{const js=await api('/api/auto-trading/config');autoConfig=js.data||{};if(apply)applyPaperConfig(autoConfig);else{renderPaperStrategyCatalog(autoConfig);renderPaperConfigSummary(autoConfig)}}catch(e){$('paperConfigSummary').textContent='总控台配置读取失败：'+e}}
async function savePaperConfig(){const cfg=collectPaperAutoConfig();const js=await api('/api/auto-trading/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cfg)});applyPaperConfig(js.data||cfg);log('已保存实时模拟配置到总控台')}
function selectPaperPreset(key){const preset=autoConfig?.beginner_presets?.[key];if(!preset){log('预设尚未加载，请先读取总控台配置','WARN');return}if(preset.strategy_combo)setPaperCombo(preset.strategy_combo);if(preset.position_sizing)$('positionSizing').value=preset.position_sizing;const r=preset.risk_controls||{};if(r.stop_loss_pct!=null)$('stopLossPct').value=r.stop_loss_pct;if(r.take_profit_pct!=null)$('takeProfitPct').value=r.take_profit_pct;if(r.max_drawdown_pct!=null)$('maxDrawdownPct').value=r.max_drawdown_pct;if(r.max_single_position_pct!=null)$('maxSinglePositionPct').value=r.max_single_position_pct;if(r.min_cash_pct!=null)$('minCashPct').value=r.min_cash_pct;renderPaperConfigSummary(autoConfig);log('已套用预设：'+(preset.label||key))}
async function sessionInfo(){try{return (await api('/api/calendar/status?symbol='+(symbols()[0]||'300750'))).data||{}}catch(e){return {can_refresh:false,label:'交易日历读取失败'}}}
async function fetchQuotesForRun(){const syms=symbols();if(!syms.length)return[];try{const js=await api('/api/quotes?symbols='+encodeURIComponent(syms.join(','))+'&force=false&refresh=false');return js.data||[]}catch(e){log('行情快照失败，将由后端统一数据层补行情或标记缺失：'+e);return syms.map(s=>({symbol:s,name:s,quote_hydrate_request:true,missing_data:['quote_snapshot_missing'],source:'quote_fetch_failed'}))}
}
function scoreFromQuote(q,session){const chg=Number(q.change_pct||0),vr=Number(q.volume_ratio||1),turn=Number(q.turnover||0),amt=Number(q.amount||0);const fundFlow=(Number.isFinite(amt)&&amt>0)?Math.max(25,Math.min(88,52+Math.log10(Math.max(amt,1))*2+Math.min(vr||1,3)*3)):null;return {technical_score:Number.isFinite(chg)?Math.max(20,Math.min(88,58+chg*3+Math.min(vr||1,3)*4)):null,information_score:null,fundamental_score:null,fund_flow_score:fundFlow,market_score:session.can_refresh?58:null,anomaly_features:{price_jump_pct:Math.abs(chg||0),volume_ratio:vr,turnover_rate:turn},score_source:'quote_snapshot_observation'}}
async function startEngine(){const payload=collectPaperAutoConfig();payload.symbols=symbols();payload.initial_cash=Number($('cash').value||payload.initial_cash||100000);payload.interval_seconds=intervalSec();payload.horizon=$('horizon').value;const js=await api('/api/realtime-paper/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});renderStatus(js);renderSymbolTabs();startLoop();await runOneCycle('start');log('已启动自动模拟：每 '+intervalSec()+' 秒运行一轮，策略组合 '+paperCombo().join('/'))}
async function stopEngine(){clearLoop();const js=await api('/api/realtime-paper/stop',{method:'POST'});renderStatus(js);$('mNext').textContent='已停止';log('已停止自动模拟')}
function clearLoop(){if(loopTimer)clearInterval(loopTimer);if(countTimer)clearInterval(countTimer);loopTimer=null;countTimer=null;nextAt=null}
function startLoop(){clearLoop();const sec=intervalSec();nextAt=Date.now()+sec*1000;loopTimer=setInterval(()=>runOneCycle('auto'),sec*1000);countTimer=setInterval(updateCountdown,1000);updateCountdown()}
function updateCountdown(){if(!nextAt){$('mNext').textContent='--';return}const left=Math.max(0,Math.ceil((nextAt-Date.now())/1000));$('mNext').textContent=left+'秒';if(left===0)nextAt=Date.now()+intervalSec()*1000}
async function runOneCycle(source='manual'){if(cycleBusy){log('上一轮仍在运行，已跳过本次触发');return}cycleBusy=true;try{const session=await sessionInfo();const quotes=await fetchQuotesForRun();const manualReplay=!session.can_refresh;lastMode=manualReplay?'休市纸面观察':'盘中实时模拟';$('mMode').textContent=lastMode;let ok=0;const cfg=collectPaperAutoConfig();const comboNames=paperCombo().map(k=>paperStrategyLabel(k,autoConfig)).join('、');for(const q of quotes){const price=Number(q.last||q.price||0);const scores=scoreFromQuote(q,session);const payload={...cfg,symbol:q.symbol,name:q.name||q.symbol,price:price||undefined,last:price||undefined,quote:q,quote_ts:q.ts,now:new Date().toISOString(),horizon:$('horizon').value,is_trading_session:!!session.can_refresh,manual_replay:manualReplay,quote_hydrate_request:true,missing_data:q.missing_data||[],evidence:[manualReplay?'休市纸面观察：使用缓存/快照生成观察信号，不代表实时成交':'页面自动模拟：使用当前真实行情快照生成纸面信号',`策略组合：${comboNames||'--'}`,`风控：止损${cfg.risk_controls.stop_loss_pct}% 止盈${cfg.risk_controls.take_profit_pct}% 最大回撤${cfg.risk_controls.max_drawdown_pct}%`],...scores};await api('/api/realtime-paper/tick',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});ok++}await refreshAll();$('mLast').textContent=new Date().toLocaleTimeString();log((source==='manual'?'手动执行':'自动执行')+'一轮完成：'+ok+'/'+quotes.length+' 只 · '+lastMode)}catch(e){log('执行一轮失败：'+e)}finally{cycleBusy=false}}
function renderStatus(js){const st=js.state||js.data?.state||{};const p=js.portfolio||js.data||{};$('mStatus').textContent=st.status||'--';$('mMode').textContent=lastMode||((st.is_trading_session?'盘中实时模拟':'休市纸面回放'));$('mEquity').textContent=money(p.equity);$('mCash').textContent=money(p.cash)+' / '+money(p.available_cash);$('mRet').textContent=pct(p.total_return_pct)+' / '+pct((p.max_drawdown||0)*100);$('mRet').className=cls(p.total_return_pct);$('mMv').textContent=money(p.market_value);$('symbolSummary').textContent=(st.config?.symbols||symbols()).join(', ')||'--';$('riskBox').innerHTML=`状态 ${esc(st.status||'--')}；交易时段 ${st.is_trading_session?'是':'否'}；新鲜度 ${esc(st.freshness_status||'--')}<br>paper_only=true；real_broker_connected=false<br><span class="warn">休市自动模拟只做纸面回放，不代表真实盘中成交；真实券商接口默认禁用。</span>`}
function renderPortfolio(js){const p=js.data||js.portfolio||{};renderStatus({state:(window.lastState||{}),portfolio:p});const pos=p.positions||{};$('positions').innerHTML=Object.keys(pos).length?Object.values(pos).map(x=>`<div class="pos-row"><b>${esc(x.symbol)}</b><div>${esc(x.name||'')} ${x.quantity}股<br>成本 ${fmt(x.avg_cost)} · 现价 ${fmt(x.market_price)} · 市值 ${money(x.market_value)} · 浮盈 ${money(x.unrealized_pnl)}</div></div>`).join(''):'暂无持仓'}
function renderSymbolTabs(){const syms=['all',...new Set([...symbols(),...lastSignals.map(x=>x.symbol).filter(Boolean)])];$('symbolTabs').innerHTML=syms.map(s=>`<button class="${selectedSymbol===s?'active':''}" onclick="selectedSymbol='${s}';renderSignals({data:lastSignals});renderOrders(window.__lastOrders||{data:[]});renderSymbolTabs()">${s==='all'?'全部':esc(s)}</button>`).join('')}
function renderSignals(js){lastSignals=js.data||lastSignals||[];const rows=selectedSymbol==='all'?lastSignals:lastSignals.filter(x=>String(x.symbol)===String(selectedSymbol));$('signalRows').innerHTML=rows.map(x=>{const ctl=x.strategy_controls||{},evt=x.event_watch_context||{};const extra=[ctl.strategy_combo?`策略:${ctl.strategy_combo.join('/')}`:'',ctl.stop_loss_pct!=null?`止损/止盈:${ctl.stop_loss_pct}%/${ctl.take_profit_pct??'--'}%`:'',evt.event_watch_enabled?`事件:${(evt.missing_data||[]).join('/')||'已检查'}`:''].filter(Boolean).join('；');return `<tr><td>${esc((x.timestamp||'').replace('T',' ').slice(11,19))}</td><td>${esc(x.name||'--')}</td><td>${esc(x.symbol)}</td><td>${esc(x.action)}</td><td>${fmt(x.final_score,1)}</td><td>${fmt(x.fundamental_score,1)} / ${fmt(x.technical_score,1)} / ${fmt(x.information_score,1)} / ${fmt(x.fund_flow_score,1)} / ${fmt(x.market_score,1)}</td><td>${fmt(x.anomaly_score,1)}</td><td>${pct((x.target_weight||0)*100)}</td><td>${esc(x.session_mode||'--')}</td><td class="reason">${esc(x.reason||'--')}<br><span class="mini">${esc(extra||'统一评分/风控内核')}</span></td><td class="evidence">${esc((x.evidence||[]).slice(0,4).join('；'))}</td></tr>`}).join('')||'<tr><td colspan="11" class="muted">暂无信号；启动自动模拟或执行一轮后显示</td></tr>';renderSymbolTabs()}
function renderOrders(js){window.__lastOrders=js;const all=js.data||[];const rows=selectedSymbol==='all'?all:all.filter(x=>String(x.symbol)===String(selectedSymbol));$('orderRows').innerHTML=rows.map(x=>`<tr><td>${esc((x.created_at||'').replace('T',' ').slice(11,19))}</td><td>${esc(x.symbol)}</td><td>${esc(x.side)}</td><td>${esc(x.status)}</td><td>${fmt(x.price)}</td><td>${x.quantity??0}</td><td>${x.filled_quantity??0}</td><td class="reason">${esc(x.reason||'--')}</td></tr>`).join('')||'<tr><td colspan="8" class="muted">暂无订单；信号未触发或风控未放行时不会生成成交</td></tr>'}
function renderAudit(js){const rows=js.data||[];$('auditBox').innerHTML=rows.slice(0,14).map(x=>`<div>${esc((x.created_at||'').replace('T',' ').slice(11,19))} <b>${esc(x.event_type)}</b> ${esc(JSON.stringify(x.payload||{})).slice(0,180)}</div>`).join('')||'暂无审计'}
async function refreshAll(){const [st,p,s,o,a]=await Promise.all([api('/api/realtime-paper/status'),api('/api/realtime-paper/portfolio'),api('/api/realtime-paper/signals'),api('/api/realtime-paper/orders'),api('/api/realtime-paper/audit')]);window.lastState=st.state;renderStatus(st);renderPortfolio(p);renderSignals(s);renderOrders(o);renderAudit(a)}
loadAutoConfig(true).finally(()=>refreshAll().catch(e=>log('初始化失败 '+e)));
</script>
</body>
</html>'''
